        function filterOptionContracts(){const value=filter.value,rows=[...table.querySelectorAll('tbody tr')],visible=rows.filter(row=>value==='ALL'||row.dataset.optionType===value);rows.forEach(row=>row.hidden=!visible.includes(row));empty.hidden=visible.length!==0;status.textContent=`${visible.length} contract${visible.length===1?'':'en'} zichtbaar · ${value==='ALL'?'alle types':value}`;}
        filter.addEventListener('change',filterOptionContracts);reset.addEventListener('click',()=>{filter.value='ALL';filterOptionContracts();showToast('Option contract filter gereset.')});
        filterOptionContracts();
        const normalizeOptionRouteLabel=()=>{if(document.body.dataset.route!=='Actions'||document.querySelector('.module-nav-select')?.value!=='option-contract-panel')return;const option=document.querySelector('.module-nav-select option');if(option)option.textContent='Option contracts & Greeks';const subtitle=document.getElementById('page-subtitle');if(subtitle)subtitle.textContent='Actions / Option contracts & Greeks';};
        document.querySelector('[data-nav="Actions"]')?.addEventListener('click',()=>setTimeout(normalizeOptionRouteLabel,0));
