      (() => {
        const schedule = document.getElementById('bond-cashflow-schedule');
        const overviewState = document.querySelector('#analytics-bond-overview-panel .page-head .pill');
        const trace = document.getElementById('bond-profile-trace-id');
        const correlation = document.getElementById('bond-profile-correlation-id');
        if (!schedule || !overviewState || !trace || !correlation) return;
        overviewState.id = 'bond-overview-state';
        overviewState.setAttribute('role', 'status');
        overviewState.setAttribute('aria-live', 'polite');
        window.__bondRunEvidence = { trace: trace.textContent, correlation: correlation.textContent, error: '—' };
        const nativeFetch = window.fetch.bind(window);
        window.fetch = async (...args) => {
          const response = await nativeFetch(...args);
          const payload = await response.clone().json().catch(() => ({}));
          const nextEvidence = {
            trace: payload.trace_id || response.headers.get('x-trace-id') || window.__bondRunEvidence.trace,
            correlation: payload.correlation_id || response.headers.get('x-correlation-id') || window.__bondRunEvidence.correlation,
            error: window.__bondRunEvidence.error
          };
          if (!response.ok) {
            if (payload.error) {
              nextEvidence.error = `${payload.error} · trace ${nextEvidence.trace} · correlation ${nextEvidence.correlation}`;
              return new Response(JSON.stringify({ ...payload, error: nextEvidence.error }), { status: response.status, headers: response.headers });
            }
          }
          window.__bondRunEvidence = nextEvidence;
          return response;
        };
        const sync = () => {
          const generated = document.getElementById('bond-profile-status')?.textContent === 'generated · read-only';
          overviewState.textContent = generated ? 'calculated · read-only' : 'synthetic fixture · read-only';
          if (window.__bondRunEvidence.trace) trace.textContent = window.__bondRunEvidence.trace;
          if (window.__bondRunEvidence.correlation) correlation.textContent = window.__bondRunEvidence.correlation;
        };
        document.getElementById('bond-profile-reset')?.addEventListener('click', () => { overviewState.textContent = 'synthetic fixture · read-only'; });
        new MutationObserver(sync).observe(schedule, { childList: true, characterData: true, subtree: true });
        sync();
      })();
    

      function addChartAxisLabels({ chartId, xLabel, yLabel }) {
        const target = document.getElementById(chartId);
        const chart = target?.matches('svg') ? target.closest('.chart') : target;
        if (!chart || chart.querySelector('.chart-axis-labels')) return;
        const labels = document.createElement('div');
        labels.id = `${chartId}-axis-labels`;
        labels.className = 'chart-axis-labels';
        const xAxis = document.createElement('span');
        xAxis.id = `${chartId}-x-axis-label`;
        xAxis.className = 'chart-axis-label x';
        xAxis.textContent = xLabel;
        const yAxis = document.createElement('span');
        yAxis.id = `${chartId}-y-axis-label`;
        yAxis.className = 'chart-axis-label y';
        yAxis.textContent = yLabel;
        labels.append(xAxis, yAxis);
        chart.append(labels);
        chart.setAttribute('aria-describedby', `${chart.getAttribute('aria-describedby') || ''} ${labels.id}`.trim());
        const svg = chart.querySelector('svg');
        if (svg) svg.setAttribute('aria-describedby', `${svg.getAttribute('aria-describedby') || ''} ${labels.id}`.trim());
      }
      addChartAxisLabels({ chartId:'portfolio-line-chart', xLabel:'Datum', yLabel:'Portfoliowaarde (EUR)' });
      addChartAxisLabels({ chartId:'dividend-chart', xLabel:'Periode', yLabel:'Dividendinkomen (EUR)' });
    

